<?php require '../../includes/config.php';require '../../includes/layout.php';require_login(['admin']);if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$id=(int)$_POST['ticket_id'];if(!empty($_POST['department_id'])){$dept=(int)$_POST['department_id'];$stmt=$conn->prepare('UPDATE tickets SET department_id=? WHERE id=?');$stmt->bind_param('ii',$dept,$id);$stmt->execute();$status='In Progress';$stmt=$conn->prepare("UPDATE tickets SET status=? WHERE id=? AND status='Submitted'");$stmt->bind_param('si',$status,$id);$stmt->execute();}$message='Case routed successfully.';}if(isset($_POST['action'])&&$_POST['action']==='note'){csrf_verify();$id=(int)$_POST['ticket_id'];$text=trim($_POST['message']);if($text){$uid=$_SESSION['user']['id'];$stmt=$conn->prepare('INSERT INTO ticket_updates(ticket_id,user_id,message) VALUES(?,?,?)');$stmt->bind_param('iis',$id,$uid,$text);$stmt->execute();}}$depts=$conn->query('SELECT id,name FROM departments ORDER BY name')->fetch_all(MYSQLI_ASSOC);$tickets=$conn->query('SELECT t.*,u.full_name,d.name department_name FROM tickets t JOIN users u ON u.id=t.student_id LEFT JOIN departments d ON d.id=t.department_id ORDER BY t.created_at DESC')->fetch_all(MYSQLI_ASSOC);admin_shell('All Complaints','tickets');?><div class="page-header"><h2>Complaints and Routing</h2></div><?php if(!empty($message))echo'<div class="alert alert-success">'.e($message).'</div>';?><div class="content-card table-wrap"><table><thead><tr><th>Reference</th><th>Student</th><th>Topic / Subject</th><th>Department</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($tickets as $t){echo'<tr><td><b>'.e($t['ref_number']).'</b></td><td>'.e($t['full_name']).'<br><small>'.e(date('d M Y',strtotime($t['created_at']))).'</small></td><td>'.e($t['topic']).'<br><small>'.e($t['subject']).'</small></td><td>'.e($t['department_name']?:'Not routed').'</td><td>'.e($t['status']).'</td><td><form method="post" style="margin:0"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="ticket_id" value="'.(int)$t['id'].'"><select name="department_id" required style="min-width:150px"><option value="">Route to...</option>';foreach($depts as $d)echo'<option value="'.(int)$d['id'].'" '.($d['id']==$t['department_id']?'selected':'').'>'.e($d['name']).'</option>';echo'</select><button class="btn btn-primary" style="padding:7px 10px">Route</button></form></td></tr>'; }?></tbody></table></div><?php dashboard_footer(); ?>